#include <bits/stdc++.h>
using namespace std;

int main() {
    int N;
    cin >> N;

    int ones = 0, twos = 0;

    for (int i = 0; i < N; i++) {
        int num;
        cin >> num;

        ones = (ones ^ num) & ~twos;
        twos = (twos ^ num) & ~ones;
    }

    cout << ones << '\n';
    return 0;
}
